<?php
require_once '../config/database.php';require_once '../config/auth.php';$u=requireAuth();requireCsrf();$in=readJson();$token=trim($in['token']??'');$plat=strtoupper(trim($in['plataforma']??'WEB'));if(strlen($token)<20||!in_array($plat,['ANDROID','IOS','WEB'],true))jsonResponse(false,'Token inválido.',[],400);$s=$conn->prepare("INSERT INTO push_tokens(usuario_id,token,plataforma,ativo,ultimo_uso) VALUES(?,?,?,1,NOW()) ON DUPLICATE KEY UPDATE usuario_id=VALUES(usuario_id),plataforma=VALUES(plataforma),ativo=1,ultimo_uso=NOW()");$s->bind_param('iss',$u['id'],$token,$plat);$s->execute();jsonResponse(true,'Token registrado.');
